def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 55.0)
        return min(budget, 28.0)

    expected_slots = max(1, int(supply // WATER_REQ))

    prev_bids = []
    urgent_prev_bids = []
    bob_like_bid = None
    rich_aggressive = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append((agent_id, float(bid)))
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(bid))
            if agent_id == 'Bob':
                bob_like_bid = float(bid)
        if opp.get('budget', 0) >= 300 and opp.get('daily_salary', 0) >= 70:
            if bid is not None and float(bid) >= 90:
                rich_aggressive += 1

    highest_prev = 0.0
    if prev_bids:
        highest_prev = max(b for _, b in prev_bids)

    base = 32.0
    if bob_like_bid is not None:
        base = bob_like_bid + 2.0
    elif prev_bids:
        sorted_bids = sorted([b for _, b in prev_bids])
        base = sorted_bids[int(len(sorted_bids) // 2)] + 2.0

    if expected_slots <= 1:
        base += 18.0
    elif expected_slots >= 2:
        base -= 4.0

    if hp <= 2:
        base = max(base, 95.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, 72.0)

    if urgent_prev_bids:
        base = max(base, max(urgent_prev_bids) + 3.0)

    if rich_aggressive >= expected_slots and hp > 4 and no_water_days == 0:
        base = min(base, 36.0)

    if highest_prev >= 120 and hp > 4 and no_water_days == 0:
        base = min(base, 34.0)

    if day >= 8:
        if hp <= 4 or no_water_days >= 1:
            base += 10.0
        else:
            base += 4.0

    if budget < 120:
        base = min(base, budget * 0.55)
    elif budget < 220:
        base = min(base, budget * 0.7)

    if hp >= 8 and no_water_days == 0 and expected_slots >= 2 and highest_prev >= 100:
        base = min(base, 30.0)

    if base < 0:
        base = 0.0
    if base > budget:
        base = budget
    return float(base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    # Filter out opponents who are not alive or are known non-players (like David)
    alive_opponents = [o for o in opponents_status.values() if o['alive'] and o['agent_id'] != 'David']

    # If no real opponents, bid a minimal amount to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine the highest bid from yesterday. Default to 0 if no bids.
    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Strategy based on my HP and opponent's previous behavior

    # If I'm in critical HP (2 or less), bid very aggressively to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95) # Bid 142.5

    # If the highest previous bid was very high (e.g., Eric's typical high bids)
    # DAILY_SALARY * 0.85 = 150 * 0.85 = 127.5
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If my HP is good (>3), I can afford to let opponents overpay and conserve budget
        if my_status['hp'] > 3:
            return min(my_status['budget'], DAILY_SALARY * 0.3) # Bid 45
        # If my HP is low (3 or less), I must compete aggressively
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.95) # Bid 142.5

    # Otherwise (highest_prev_bid was moderate or low)
    # Try to win by bidding slightly above the highest previous bid, with a minimum floor.
    # DAILY_SALARY * 0.5 = 150 * 0.5 = 75
    return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
